/**
 * A change
 */
external interface IChange {
    val originalStartLineNumber: Double
    val originalEndLineNumber: Double
    val modifiedStartLineNumber: Double
    val modifiedEndLineNumber: Double
}

/**
 * A character level change.
 */
external interface ICharChange : IChange {
    val originalStartColumn: Double
    val originalEndColumn: Double
    val modifiedStartColumn: Double
    val modifiedEndColumn: Double
}

/**
 * A line change
 */
external interface ILineChange : IChange {
    val charChanges: Array<ICharChange>?
}

external interface IDimension {
    var width: Double
    var height: Double
}

/**
 * A builder and helper for edit operations for a command.
 */
external interface IEditOperationBuilder {
    /**
     * Add a new edit operation (a replace operation).
     * @param range The range to replace (delete). May be empty to represent a simple insert.
     * @param text The text to replace with. May be null to represent a simple delete.
     */
    fun addEditOperation(range: IRange, text: String?, forceMoveMarkers: Boolean? = definedExternally): Unit
    /**
     * Add a new edit operation (a replace operation).
     * The inverse edits will be accessible in `ICursorStateComputerData.getInverseEditOperations()`
     * @param range The range to replace (delete). May be empty to represent a simple insert.
     * @param text The text to replace with. May be null to represent a simple delete.
     */
    fun addTrackedEditOperation(range: IRange, text: String?, forceMoveMarkers: Boolean? = definedExternally): Unit
    /**
     * Track `selection` when applying edit operations.
     * A best effort will be made to not grow/expand the selection.
     * An empty selection will clamp to a nearby character.
     * @param selection The selection to track.
     * @param trackPreviousOnEmpty If set, and the selection is empty, indicates whether the selection
     * should clamp to the previous or the next character.
     * @return A unique identifier.
     */
    fun trackSelection(selection: Selection, trackPreviousOnEmpty: Boolean? = definedExternally): String
}

/**
 * A helper for computing cursor state after a command.
 */
external interface ICursorStateComputerData {
    /**
     * Get the inverse edit operations of the added edit operations.
     */
    fun getInverseEditOperations(): Array<IValidEditOperation>
    /**
     * Get a previously tracked selection.
     * @param id The unique identifier returned by `trackSelection`.
     * @return The selection.
     */
    fun getTrackedSelection(id: String): Selection
}

/**
 * A command that modifies text / cursor state on a model.
 */
external interface ICommand {
    /**
     * Get the edit operations needed to execute this command.
     * @param model The model the command will execute on.
     * @param builder A helper to collect the needed edit operations and to track selections.
     */
    fun getEditOperations(model: ITextModel, builder: IEditOperationBuilder): Unit
    /**
     * Compute the cursor state after the edit operations were applied.
     * @param model The model the command has executed on.
     * @param helper A helper to get inverse edit operations and to get previously tracked selections.
     * @return The cursor state after the command executed.
     */
    fun computeCursorState(model: ITextModel, helper: ICursorStateComputerData): Selection
}

/**
 * A model for the diff editor.
 */
external interface IDiffEditorModel {
    /**
     * Original model.
     */
    var original: ITextModel
    /**
     * Modified model.
     */
    var modified: ITextModel
}

external interface IDiffEditorViewModel : IDisposable {
    val model: IDiffEditorModel
    fun waitForDiff(): Promise<Unit>
}

/**
 * An event describing that an editor has had its model reset (i.e. `editor.setModel()`).
 */
external interface IModelChangedEvent {
    /**
     * The `uri` of the previous model or null.
     */
    val oldModelUrl: Uri?
    /**
     * The `uri` of the new model or null.
     */
    val newModelUrl: Uri?
}

external interface IContentSizeChangedEvent {
    val contentWidth: Double
    val contentHeight: Double
    val contentWidthChanged: Boolean
    val contentHeightChanged: Boolean
}

external interface INewScrollPosition {
