    /**
     * Replace all previous decorations with `newDecorations`.
     */
    fun `set`(newDecorations: Array<IModelDeltaDecoration>): Array<String>
    /**
     * Append `newDecorations` to this collection.
     */
    fun append(newDecorations: Array<IModelDeltaDecoration>): Array<String>
    /**
     * Remove all previous decorations.
     */
