     * Execute multiple (concomitant) commands on the editor.
     * @param source The source of the call.
     * - `command` — The commands to execute
     */
    fun executeCommands(source: String?, commands: Array<ICommand?>): Unit
    /**
     * Scroll vertically or horizontally as necessary and reveal the current cursors.
     */
    fun revealAllCursors(revealHorizontal: Boolean, minimalReveal: Boolean? = definedExternally): Unit
    /**
     * Get all the decorations on a line (filtering out decorations from other editors).
     */
    fun getLineDecorations(lineNumber: Double): Array<IModelDecoration>?
    /**
     * Get all the decorations for a range (filtering out decorations from other editors).
     */
    fun getDecorationsInRange(range: Range): Array<IModelDecoration>?
    /**
     * Get the font size at a given position
     * @param position the position for which to fetch the font size
     */
    fun getFontSizeAtPosition(position: IPosition): String?
    /**
     * All decorations added through this call will get the ownerId of this editor.
     * @deprecated Use `createDecorationsCollection`
     * @see createDecorationsCollection
     */
    fun deltaDecorations(oldDecorations: Array<String>, newDecorations: Array<IModelDeltaDecoration>): Array<String>
    /**
     * Remove previously added decorations.
     */
    fun removeDecorations(decorationIds: Array<String>): Unit
    /**
     * Get the layout info for the editor.
     */
    fun getLayoutInfo(): EditorLayoutInfo
    /**
     * Returns the ranges that are currently visible.
     * Does not account for horizontal scrolling.
     */
    fun getVisibleRanges(): Array<Range>
    /**
     * Get the vertical position (top offset) for the line's top w.r.t. to the first line.
     */
    fun getTopForLineNumber(lineNumber: Double, includeViewZones: Boolean? = definedExternally): Double
    /**
     * Get the vertical position (top offset) for the line's bottom w.r.t. to the first line.
     */
    fun getBottomForLineNumber(lineNumber: Double): Double
    /**
     * Get the vertical position (top offset) for the position w.r.t. to the first line.
     */
    fun getTopForPosition(lineNumber: Double, column: Double): Double
    /**
     * Get the line height for a model position.
     */
    fun getLineHeightForPosition(position: IPosition): Double
    /**
     * Write the screen reader content to be the current selection
     */
    fun writeScreenReaderContent(reason: String): Unit
    /**
     * Returns the editor's container dom node
     */
    fun getContainerDomNode(): HTMLElement
    /**
     * Returns the editor's dom node
     */
    fun getDomNode(): HTMLElement?
    /**
     * Add a content widget. Widgets must have unique ids, otherwise they will be overwritten.
     */
    fun addContentWidget(widget: IContentWidget): Unit
    /**
     * Layout/Reposition a content widget. This is a ping to the editor to call widget.getPosition()
     * and update appropriately.
     */
    fun layoutContentWidget(widget: IContentWidget): Unit
    /**
     * Remove a content widget.
     */
    fun removeContentWidget(widget: IContentWidget): Unit
    /**
     * Add an overlay widget. Widgets must have unique ids, otherwise they will be overwritten.
     */
    fun addOverlayWidget(widget: IOverlayWidget): Unit
    /**
     * Layout/Reposition an overlay widget. This is a ping to the editor to call widget.getPosition()
     * and update appropriately.
     */
    fun layoutOverlayWidget(widget: IOverlayWidget): Unit
    /**
     * Remove an overlay widget.
     */
    fun removeOverlayWidget(widget: IOverlayWidget): Unit
    /**
     * Add a glyph margin widget. Widgets must have unique ids, otherwise they will be overwritten.
     */
    fun addGlyphMarginWidget(widget: IGlyphMarginWidget): Unit
    /**
     * Layout/Reposition a glyph margin widget. This is a ping to the editor to call widget.getPosition()
     * and update appropriately.
     */
    fun layoutGlyphMarginWidget(widget: IGlyphMarginWidget): Unit
    /**
     * Remove a glyph margin widget.
     */
    fun removeGlyphMarginWidget(widget: IGlyphMarginWidget): Unit
    /**
     * Change the view zones. View zones are lost when a new model is attached to the editor.
     */
    fun changeViewZones(callback: (IViewZoneChangeAccessor) -> Unit): Unit
    /**
     * Get the horizontal position (left offset) for the column w.r.t to the beginning of the line.
     * This method works only if the line `lineNumber` is currently rendered (in the editor's viewport).
     * Use this method with caution.
     */
    fun getOffsetForColumn(lineNumber: Double, column: Double): Double
    fun getWidthOfLine(lineNumber: Double): Double
    /**
     * Force an editor render now.
     */
    fun render(forceRedraw: Boolean? = definedExternally): Unit
    /**
     * Render the editor at the next animation frame.
     */
    fun renderAsync(forceRedraw: Boolean? = definedExternally): Unit
    /**
     * Get the hit test target at coordinates `clientX` and `clientY`.
     * The coordinates are relative to the top-left of the viewport.
     *
     * @returns Hit test target or null if the coordinates fall outside the editor or the editor has no model.
     */
    fun getTargetAtClientPoint(clientX: Double, clientY: Double): IMouseTarget?
    /**
     * Get the visible position for `position`.
     * The result position takes scrolling into account and is relative to the top left corner of the editor.
     * Explanation 1: the results of this method will change for the same `position` if the user scrolls the editor.
     * Explanation 2: the results of this method will not change if the container of the editor gets repositioned.
     * Warning: the results of this method are inaccurate for positions that are outside the current editor viewport.
     */
    fun getScrolledVisiblePosition(position: IPosition): ICodeEditorResultOptions?
    /**
     * Apply the same font settings as the editor to `target`.
     */
    fun applyFontInfo(target: HTMLElement): Unit
    fun setBanner(bannerDomNode: HTMLElement?, height: Double): Unit
    /**
     * Is called when the model has been set, view state was restored and options are updated.
     * This is the best place to compute data for the viewport (such as tokens).
     */
    var handleInitialized: (() -> Unit)?
}

/**
 * A rich diff editor.
 */
external interface IDiffEditor : IEditor {
    /**
     * @see {@link ICodeEditor.getContainerDomNode}
     */
    fun getContainerDomNode(): HTMLElement
    /**
     * An event emitted when the diff information computed by this diff editor has been updated.
     * @event
     */
    val onDidUpdateDiff: IEvent<Unit>
    /**
     * An event emitted when the diff model is changed (i.e. the diff editor shows new content).
     * @event
     */
    val onDidChangeModel: IEvent<Unit>
    /**
     * Saves current view state of the editor in a serializable object.
     */
    fun saveViewState(): IDiffEditorViewState?
    /**
     * Restores the view state of the editor from a serializable object generated by `saveViewState`.
     */
    fun restoreViewState(state: IDiffEditorViewState?): Unit
    /**
     * Type the getModel() of IEditor.
     */
    fun getModel(): IDiffEditorModel?
    fun createViewModel(model: IDiffEditorModel): IDiffEditorViewModel
    /**
     * Sets the current model attached to this editor.
     * If the previous model was created by the editor via the value key in the options
     * literal object, it will be destroyed. Otherwise, if the previous model was set
     * via setModel, or the model key in the options literal object, the previous model
     * will not be destroyed.
     * It is safe to call setModel(null) to simply detach the current model from the editor.
     */
    fun setModel(model: IDiffEditorModelOrIDiffEditorViewModel?): Unit
    /**
     * Get the computed diff information.
     */
    fun getLineChanges(): Array<ILineChange>?
    /**
     * Update the editor's options after the editor has been created.
     */
    fun updateOptions(newOptions: IDiffEditorOptions): Unit
    /**
     * Jumps to the next or previous diff.
     */
    fun goToDiff(target: target): Unit
    /**
     * Scrolls to the first diff.
     * (Waits until the diff computation finished.)
     */
    fun revealFirstDiff(): JsAny
    fun accessibleDiffViewerNext(): Unit
    fun accessibleDiffViewerPrev(): Unit
    fun handleInitialized(): Unit
}

external interface IEditorZoom {
    val onDidChangeZoomLevel: IEvent<Double>
    fun getZoomLevel(): Double
    fun setZoomLevel(zoomLevel: Double): Unit
}

typealias IReadOnlyModel = ITextModel

typealias IModel = ITextModel

